                    if (index + 1 < end)
                    {
                        currentByteIndex = index + 1;
                        currentByteOffset = offset;
                        return FIT_FALSE;
                    }
                    index = end;
                }
                continue;
            }

            if (decodeReturn == RETURN_END_OF_FILE)
            {
                currentByteIndex = index + 1;
                currentByteOffset = offset + 1;
                return FIT_TRUE;
            }

            // default
            currentByteIndex = index;
            currentByteOffset = offset + 1;
            return FIT_TRUE;
        }

        currentByteOffset = offset;
        currentByteIndex = 0;
    } while ( file->good() );

    if ((streamIsComplete == FIT_TRUE) && (skipHeader == FIT_FALSE))
